import CoreData

/// An entity managed by a `Database`.
///
/// The protocol imposes no identifier: entities with a business key adopt
/// `IdentifiableDatabaseObject` on top of it. What it does require is the schema the entity belongs
/// to, and the typed query and sort types its fetches are expressed with — usually generated by the
/// `@Entity` macro, or written by hand following the same shape.
///
public protocol DatabaseObject: NSManagedObject {

    /// The schema the entity belongs to. Every helper takes a `DatabaseContext<Schema>`.
    associatedtype Schema: DatabaseSchema

    /// The typed predicate of the entity, resolved by implicit member: `.name("x")`, `.score(.greaterThan(2))`.
    associatedtype Query: EntityQuery where Query.Root == Self

    /// The typed sort descriptor of the entity: `.name`, `.createdAt.descending`.
    associatedtype Sort: EntitySort where Sort.Root == Self

    /// Called after the object's values were rewritten in bulk (`update(with:)`), so that
    /// derived caches can be dropped. Does nothing by default.
    func didUpdate()
}

extension DatabaseObject {

    /// The Core Data entity name, by convention the class name.
    public static var entityName: String {
        String(describing: Self.self)
    }

    public func didUpdate() { }
}
